CREATE TABLE organization_roles (id UUID PRIMARY KEY, code VARCHAR(40) NOT NULL UNIQUE, name VARCHAR(40) NOT NULL);
INSERT INTO organization_roles(id,code,name) VALUES
 ('00000000-0000-0000-0000-000000000001','MEMBER','普通成员'),('00000000-0000-0000-0000-000000000002','VICE_MINISTER','副部长'),('00000000-0000-0000-0000-000000000003','MINISTER','部长'),('00000000-0000-0000-0000-000000000004','VICE_PRESIDENT','副会长'),('00000000-0000-0000-0000-000000000005','PRESIDENT','会长'),('00000000-0000-0000-0000-000000000006','ADVISOR','指导老师');
CREATE TABLE user_organization_roles (id UUID PRIMARY KEY,user_id UUID NOT NULL REFERENCES users(id),role_id UUID NOT NULL REFERENCES organization_roles(id),granted_by UUID,granted_at TIMESTAMPTZ NOT NULL,revoked_by UUID,revoked_at TIMESTAMPTZ, UNIQUE(user_id,role_id));
CREATE TABLE membership_applications (id UUID PRIMARY KEY,user_id UUID NOT NULL REFERENCES users(id),real_name VARCHAR(40) NOT NULL,student_number VARCHAR(40) NOT NULL,college VARCHAR(100) NOT NULL,major VARCHAR(100) NOT NULL,grade VARCHAR(40) NOT NULL,phone VARCHAR(30) NOT NULL,reason VARCHAR(500),status VARCHAR(20) NOT NULL,reviewer_user_id UUID,review_comment VARCHAR(500),reviewed_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX uq_membership_application_pending ON membership_applications(user_id) WHERE status='PENDING';
CREATE INDEX idx_membership_applications_status_created ON membership_applications(status,created_at);
CREATE TABLE memberships (id UUID PRIMARY KEY,user_id UUID NOT NULL UNIQUE REFERENCES users(id),member_number VARCHAR(30) NOT NULL UNIQUE,status VARCHAR(20) NOT NULL,joined_at TIMESTAMPTZ NOT NULL,left_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_memberships_status ON memberships(status);
CREATE TABLE rating_accounts (user_id UUID PRIMARY KEY REFERENCES users(id),current_rating INTEGER NOT NULL DEFAULT 1400,highest_rating INTEGER NOT NULL DEFAULT 1400,rated_matches INTEGER NOT NULL DEFAULT 0,wins INTEGER NOT NULL DEFAULT 0,losses INTEGER NOT NULL DEFAULT 0,version BIGINT NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT chk_rating_min CHECK(current_rating>=400),CONSTRAINT chk_rating_highest CHECK(highest_rating>=current_rating));
CREATE INDEX idx_rating_accounts_rating ON rating_accounts(current_rating DESC);
CREATE TABLE rating_ledger (id UUID PRIMARY KEY,user_id UUID NOT NULL REFERENCES users(id),source_type VARCHAR(20) NOT NULL,source_id UUID,competition_id UUID,match_id UUID,opponent_user_id UUID,rating_before INTEGER,rating_delta INTEGER NOT NULL,rating_after INTEGER NOT NULL,result VARCHAR(20),rule_version VARCHAR(20) NOT NULL,reason VARCHAR(500),settlement_id UUID,created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_rating_ledger_user_created ON rating_ledger(user_id,created_at DESC);
CREATE TABLE audit_logs (id UUID PRIMARY KEY,operator_user_id UUID,action VARCHAR(80) NOT NULL,target_type VARCHAR(80) NOT NULL,target_id UUID,before_json JSONB,after_json JSONB,reason VARCHAR(500),created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
